<?php

namespace MongoDB\Driver;

use MongoDB\BSON\Binary;
use MongoDB\Driver\Exception\EncryptionException;
use MongoDB\Driver\Exception\InvalidArgumentException;

/**
 * <div id="class.mongodb-driver-clientencryption" class="reference"> <h1 class="title">The MongoDB\Driver\ClientEncryption class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.7.0)</p>    <div class="section" id="mongodb-driver-clientencryption.intro">   <h2 class="title">简介</h2>   <p class="simpara">    The <span class="classname"><strong class="classname">MongoDB\Driver\ClientEncryption</strong></span> class handles    creation of data keys for client-side encryption, as well as manually    encrypting and decrypting values.   </p>  </div>    <div class="section" id="mongodb-driver-clientencryption.synopsis">   <h2 class="title">类摘要</h2>      <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>        <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\ClientEncryption</strong>     </span>     {</div>            <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants.deterministic"><var class="varname">AEAD_AES_256_CBC_HMAC_SHA_512_DETERMINISTIC</var></a></var><span class="initializer"> = AEAD_AES_256_CBC_HMAC_SHA_512-Deterministic</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants.random"><var class="varname">AEAD_AES_256_CBC_HMAC_SHA_512_RANDOM</var></a></var><span class="initializer"> = AEAD_AES_256_CBC_HMAC_SHA_512-Random</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants.algorithm-indexed"><var class="varname">ALGORITHM_INDEXED</var></a></var><span class="initializer"> = Indexed</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants.algorithm-unindexed"><var class="varname">ALGORITHM_UNINDEXED</var></a></var><span class="initializer"> = Unindexed</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants.algorithm-range"><var class="varname">ALGORITHM_RANGE</var></a></var><span class="initializer"> = Range</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>   