an class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$keyAltName</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-clientencryption.rewrapmanydatakey.php" class="methodname" style="color:#CC7832">rewrapManyDataKey</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$filter</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></div>   }</div>     </div>    <div class="section" id="mongodb-driver-clientencryption.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-clientencryption.constants.deterministic"><strong><span>MongoDB\Driver\ClientEncryption::AEAD_AES_256_CBC_HMAC_SHA_512_DETERMINISTIC</span></strong></dt>     <dd>      <span class="simpara">Specifies an algorithm for <a href="https://www.mongodb.com/docs/manual/core/csfle/fundamentals/encryption-algorithms/#deterministic-encryption" class="link external">»&nbsp;deterministic encryption</a>, which is suitable for querying.</span>     </dd>             <dt id="mongodb-driver-clientencryption.constants.random"><strong><span>MongoDB\Driver\ClientEncryption::AEAD_AES_256_CBC_HMAC_SHA_512_RANDOM</span></strong></dt>     <dd>      <span class="simpara">Specifies an algorithm for <a href="https://www.mongodb.com/docs/manual/core/csfle/fundamentals/encryption-algorithms/#randomized-encryption" class="link external">»&nbsp;randomized encryption</a></span>     </dd>             <dt id="mongodb-driver-clientencryption.constants.algorithm-indexed"><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong></dt>     <dd>      <span class="simpara">Specifies an algorithm for an indexed, encrypted payload, which can be used with queryable encryption.</span>      <span class="simpara">To insert or query with an indexed, encrypted payload, the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span> must be configured with the <span class="literal">"autoEncryption"</span> driver option. The <span class="literal">"bypassQueryAnalysis"</span> auto encryption option may be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>. The <span class="literal">"bypassAutoEncryption"</span> auto encryption option must be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>.</span>     </dd>             <dt id="mongodb-driver-clientencryption.constants.algorithm-unindexed"><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_UNINDEXED}</span></strong></dt>     <dd>      <span class="simpara">Specifies an algorithm for an unindexed, encrypted payload.</span>     </dd>             <dt id="mongodb-driver-clientencryption.constants.algorithm-range"><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong></dt>     <dd>      <span class="simpara">       Specifies an algorithm for a range encrypted payload, which can be used       with queryable encryption.      </span>      <span class="simpara">       To query with a range encrypted payload, the       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span> must be configured with the       <span class="literal">"autoEncryption"</span> driver option. The       <span class="literal">"bypassQueryAnalysis"</span> auto encryption option may be       <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>. The <span class="literal">"bypassAutoEncryption"</span> auto encryption       option must be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>.      </span>      <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:        <span class="simpara">The extension does not yet support range queries for Decimal128 BSON field types.</span>      </p></blockquote>     </dd>             <dt id="mongodb-driver-clientencryption.constants.query-type-equality"><strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_EQUALITY}</span></strong></dt>     <dd>      <span class="simpara">       Specifies an equality query type, which is used in conjunction with       <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong>.      </span>     </dd>             <dt id="mongodb-driver-clientencryption.constants.query-type-range"><strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_RANGE}</span></strong></dt>     <dd>      <span class="simpara">       Specifies a range query type, which is used in conjunction with       <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong>.      </span>     </dd>       </dl>  </div>    <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 2.0.0</td>       <td>        <span class="simpara">         Removed <strong><span>MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE_PREVIEW</span></strong>         and <strong><span>MongoDB\Driver\ClientEncryption::QUERY_TYPE_RANGE_PREVIEW</span></strong>.        </span>       </td>      </tr>      <tr>       <td>PECL mongodb 1.20.0</td>       <td>        <span class="simpara">         Added <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong>         and <strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_RANGE}</span></strong>.        </span>        <span class="simpara">         Deprecated <strong><span>MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE_PREVIEW</span></strong>         and <strong><span>MongoDB\Driver\ClientEncryption::QUERY_TYPE_RANGE_PREVIEW</span></strong>.        </span>       </td>      </tr>      <tr>       <td>PECL mongodb 1.16.0</td>       <td>        Added <strong><span>MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE_PREVIEW</span></strong>        and <strong><span>MongoDB\Driver\ClientEncryption::QUERY_TYPE_RANGE_PREVIEW</span></strong>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.14.0</td>       <td>        Added <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong>,        <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_UNINDEXED}</span></strong>,        and <strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_EQUALITY}</span></strong>.       </td>      </tr>     </tbody>       </table>  </div>  <div class="section" id="mongodb-driver-clientencryption.seealso">   <h2 class="title">参见</h2>   <ul class="simplelist">    <li><span class="function">{@link MongoDB\Driver\Manager::createClientEncryption()}</span></li>   </ul>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\ClientEncryption::addKeyAltName} — Adds an alternate name to a key document</li><li>{@link MongoDB\Driver\ClientEncryption::__construct} — Create a new ClientEncryption object</li><li>{@link MongoDB\Driver\ClientEncryption::createDataKey} — Creates a key document</li><li>{@link MongoDB\Driver\ClientEncryption::decrypt} — Decrypt a value</li><li>{@link MongoDB\Driver\ClientEncryption::deleteKey} — Deletes a key document</li><li>{@link MongoDB\Driver\ClientEncryption::encrypt} — Encrypt a value</li><li>{@link MongoDB\Driver\ClientEncryption::encryptExpression} — Encrypts a match or aggregate expression</li><li>{@link MongoDB\Driver\ClientEncryption::getKey} — Gets a key document</li><li>{@link MongoDB\Driver\ClientEncryption::getKeyByAltName} — Gets a key document by an alternate name</li><li>{@link MongoDB\Driver\ClientEncryption::getKeys} — Gets all key documents</li><li>{@link MongoDB\Driver\ClientEncryption::removeKeyAltName} — Removes an alternate name from a key document</li><li>{@link MongoDB\Driver\ClientEncryption::rewrapManyDataKey} — Rewraps data keys</li></ul></div>
 * 
 * The MongoDB\Driver\ClientEncryption class handles creation of data keys for client-side encryption, as well as manually encrypting and decrypting values.
 * @link https://www.php.net/manual/en/class.mongodb-driver-clientencryption.php
 * @since 1.7.0
 */
final class ClientEncryption
{
    public const AEAD_AES_256_CBC_HMAC_SHA_512_DETERMINISTIC = 'AEAD_AES_256_CBC_HMAC_SHA_512-Deterministic';
    public const AEAD_AES_256_CBC_HMAC_SHA_512_RANDOM = 'AEAD_AES_256_CBC_HMAC_SHA_512-Random';

    /**
     * @since 1.14.0
     */
    public const ALGORITHM_INDEXED = 'Indexed';

    /**
     * @since 1.14.0
     */
    public const ALGORITHM_UNINDEXED = 'Unindexed';

    /**
     * @since 1.20.0
     */
    public const ALGORITHM_RANGE = 'Range';

    /**
     * @since 1.14.0
     */
    public const QUERY_TYPE_EQUALITY = 'equality';

    /**
     * @since 1.20.0
     */
    public const QUERY_TYPE_RANGE = 'range';

    /**
 * <div id="mongodb-driver-clientencryption.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.14.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::__construct</span> — <span class="dc-title">Create a new ClientEncryption object</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$options</span></span>)</div>  <p class="simpara">   Constructs a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php" class="classname">MongoDB\Driver\ClientEncryption</a></span> object with the specified options.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>keyVaultClient</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span></td>          <td>The Manager used to route data key queries. This option is required (unlike with <span class="function">{@link MongoDB\Driver\Manager::createClientEncryption()}</span>).</td>         </tr>                  <tr>          <td>keyVaultNamespace</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>A fully qualified namespace (e.g. <span class="literal">"databaseName.collectionName"</span>) denoting the collection that contains all data keys used for encryption and decryption. This option is required.</td>         </tr>                  <tr>          <td>kmsProviders</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            A document containing the configuration for one or more KMS providers, which are used to encrypt data keys. Supported providers include <span class="literal">"aws"</span>, <span class="literal">"azure"</span>, <span class="literal">"gcp"</span>, <span class="literal">"kmip"</span>, and <span class="literal">"local"</span> and at least one must be specified.           </span>           <span class="simpara">            If an empty document is specified for <span class="literal">"aws"</span>,            <span class="literal">"azure"</span>, or <span class="literal">"gcp"</span>, the driver            will attempt to configure the provider using            <a href="https://github.com/mongodb/specifications/blob/master/source/client-side-encryption/client-side-encryption.rst#automatic-credentials" class="link external">»&nbsp;Automatic Credentials</a>.           </span>           <span class="simpara">            The format for <span class="literal">"aws"</span> is as follows:           </span>           <div class="example-contents"><div class="javascriptcode"><blockquote style="border:1px gray solid;">aws:&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;accessKeyId:&nbsp;&lt;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;secretAccessKey:&nbsp;&lt;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;sessionToken:&nbsp;&lt;optional&nbsp;string&gt;<br>}</blockquote></div>           </div>           <span class="simpara">            The format for <span class="literal">"azure"</span> is as follows:           </span>           <div class="example-contents"><div class="javascriptcode"><blockquote style="border:1px gray solid;">azure:&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;tenantId:&nbsp;&lt;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;clientId:&nbsp;&lt;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;clientSecret:&nbsp;&lt;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;identityPlatformEndpoint:&nbsp;&lt;optional&nbsp;string&gt;&nbsp;//&nbsp;Defaults&nbsp;to&nbsp;"login.microsoftonline.com"<br>}</blockquote></div>           </div>           <span class="simpara">            The format for <span class="literal">"gcp"</span> is as follows:           </span>           <div class="example-contents"><div class="javascriptcode"><blockquote style="border:1px gray solid;">gcp:&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;email:&nbsp;&lt;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;privateKey:&nbsp;&lt;base64&nbsp;string&gt;|&lt;MongoDB\BSON\Binary&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;endpoint:&nbsp;&lt;optional&nbsp;string&gt;&nbsp;//&nbsp;Defaults&nbsp;to&nbsp;"oauth2.googleapis.com"<br>}</blockquote></div>           </div>           <span class="simpara">            The format for <span class="literal">"kmip"</span> is as follows:           </span>           <div class="example-contents"><div class="javascriptcode"><blockquote style="border:1px gray solid;">kmip:&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;endpoint:&nbsp;&lt;string&gt;<br>}</blockquote></div>           </div>           <span class="simpara">            The format for <span class="literal">"local"</span> is as follows:           </span>           <div class="example-contents"><div class="javascriptcode"><blockquote style="border:1px gray solid;">local:&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;96-byte&nbsp;master&nbsp;key&nbsp;used&nbsp;to&nbsp;encrypt/decrypt&nbsp;data&nbsp;keys<br>&nbsp;&nbsp;&nbsp;&nbsp;key:&nbsp;&lt;base64&nbsp;string&gt;|&lt;MongoDB\BSON\Binary&gt;<br>}</blockquote></div>           </div>          </td>         </tr>                  <tr>          <td>tlsOptions</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            A document containing the TLS configuration for one or more KMS providers. Supported providers include <span class="literal">"aws"</span>, <span class="literal">"azure"</span>, <span class="literal">"gcp"</span>, and <span class="literal">"kmip"</span>. All providers support the following options:           </span>           <div class="example-contents"><div class="javascriptcode"><blockquote style="border:1px gray solid;">&lt;provider&gt;:&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;tlsCaFile:&nbsp;&lt;optional&nbsp;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;tlsCertificateKeyFile:&nbsp;&lt;optional&nbsp;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;tlsCertificateKeyFilePassword:&nbsp;&lt;optional&nbsp;string&gt;,<br>&nbsp;&nbsp;&nbsp;&nbsp;tlsDisableOCSPEndpointCheck:&nbsp;&lt;optional&nbsp;bool&gt;<br>}</blockquote></div>           </div>          </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the extension was compiled without libmongocrypt support</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-clientencryption.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.16.0</td>      <td>       <span class="simpara">        The AWS KMS provider for client-side encryption now accepts a        <span class="literal">"sessionToken"</span> option, which can be used to        authenticate with temporary AWS credentials.       </span>       <span class="simpara">        Added <span class="literal">"tlsDisableOCSPEndpointCheck"</span> to the        <span class="literal">"tlsOptions"</span> option.       </span>       <span class="simpara">        If an empty document is specified for the <span class="literal">"azure"</span> or        <span class="literal">"gcp"</span> KMS provider, the driver will attempt to        configure the provider using        <a href="https://github.com/mongodb/specifications/blob/master/source/client-side-encryption/client-side-encryption.rst#automatic-credentials" class="link external">»&nbsp;Automatic Credentials</a>.       </span>      </td>     </tr>     <tr>      <td>PECL mongodb 1.15.0</td>      <td>       <span class="simpara">        If an empty document is specified for the <span class="literal">"aws"</span> KMS        provider, the driver will attempt to configure the provider using        <a href="https://github.com/mongodb/specifications/blob/master/source/client-side-encryption/client-side-encryption.rst#automatic-credentials" class="link external">»&nbsp;Automatic Credentials</a>.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-clientencryption.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Manager::createClientEncryption()} - Create a new ClientEncryption object</span></li>   <li><a href="https://www.mongodb.com/docs/manual/core/security-explicit-client-side-encryption/" class="link external">»&nbsp;Explicit (Manual) Client-Side Field Level Encryption</a> in the MongoDB manual</li>  </ul> </div></div>
 * 
     * @since 1.14.0
     */
    final public function __construct(array $options) {}


    final public function __wakeup() {}

    /**
 * <div id="mongodb-driver-clientencryption.addkeyaltname" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::addKeyAltName</h1>  <p class="verinfo">(mongodb &gt;=1.15.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::addKeyAltName</span> — <span class="dc-title">Adds an alternate name to a key document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.addkeyaltname-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::addKeyAltName</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span> <span class="parameter" style="color:#3A95FF">\$keyId</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$keyAltName</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></div>  <p class="simpara">   Adds <span class="parameter" style="color:#3A95FF">keyAltName</span> to the set of alternate names for the   key document with the given UUID <span class="parameter" style="color:#3A95FF">keyId</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.addkeyaltname-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">keyId</span></dt>    <dd>     <span class="simpara">      A <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span> instance with subtype 4      (UUID) identifying the key document.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">keyAltName</span></dt>    <dd>     <span class="simpara">      Alternate name to add to the key document.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.addkeyaltname-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the previous version of the key document, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no document   matched.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.addkeyaltname-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> on other errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-clientencryption.addkeyaltname-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\ClientEncryption::getKeyByAltName()} - Gets a key document by an alternate name</span></li>   <li><span class="function">{@link MongoDB\Driver\ClientEncryption::removeKeyAltName()} - Removes an alternate name from a key document</span></li>  </ul> </div></div>
 * 
     * Adds an alternate name to a key document
     * @link https://www.php.net/manual/en/mongodb-driver-clientencryption.addkeyaltname.php
     * @param Binary $keyId A MongoDB\BSON\Binary instance with subtype 4 (UUID) identifying the key document.
     * @param string $keyAltName Alternate name to add to the key document.
     * @return object|null Returns the previous version of the key document, or null if no document matched.
     * @throws InvalidArgumentException On argument parsing errors.
     * @since 1.15.0
     */
    final public function addKeyAltName(Binary $keyId, string $keyAltName): ?object {}

    /**
 * <div id="mongodb-driver-clientencryption.createdatakey" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::createDataKey</h1>  <p class="verinfo">(mongodb &gt;=1.7.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::createDataKey</span> — <span class="dc-title">Creates a key document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.createdatakey-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::createDataKey</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$kmsProvider</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span></div>  <p class="simpara">   Creates a new key document and inserts it into the key vault collection.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.createdatakey-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">kmsProvider</span></dt>    <dd>     <span class="simpara">      The KMS provider (e.g. <span class="literal">"local"</span>,      <span class="literal">"aws"</span>) that will be used to encrypt the new data key.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>Data key options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>masterKey</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            The masterKey document identifies a KMS-specific key used to encrypt            the new data key. This option is required unless            <span class="parameter" style="color:#3A95FF">kmsProvider</span> is <span class="literal">"local"</span>.           </span>             <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"aws"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>region</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>key</td>       <td>string</td>       <td>Required. The Amazon Resource Name (ARN) to the AWS customer master key (CMK).</td>      </tr>      <tr>       <td>endpoint</td>       <td>string</td>       <td>Optional. An alternate host identifier to send KMS requests to. May include port number.</td>      </tr>     </tbody>       </table>    <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"azure"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>keyVaultEndpoint</td>       <td>string</td>       <td>Required. Host with optional port (e.g. "example.vault.azure.net").</td>      </tr>      <tr>       <td>keyName</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyVersion</td>       <td>string</td>       <td>Optional. A specific version of the named key. Defaults to using the key's primary version.</td>      </tr>     </tbody>       </table>    <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"gcp"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>projectId</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>location</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyRing</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyName</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyVersion</td>       <td>string</td>       <td>Optional. A specific version of the named key. Defaults to using the key's primary version.</td>      </tr>      <tr>       <td>endpoint</td>       <td>string</td>       <td>Optional. Host with optional port. Defaults to "cloudkms.googleapis.com".</td>      </tr>     </tbody>       </table>    <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"kmip"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>keyId</td>       <td>string</td>       <td>Optional. Unique identifier to a 96-byte KMIP secret data managed object. If unspecified, the driver creates a random 96-byte KMIP secret data managed object.</td>      </tr>      <tr>       <td>endpoint</td>       <td>string</td>       <td>Optional. Host with optional port.</td>      </tr>      <tr>       <td>delegated</td>       <td>bool</td>       <td>Optional. If true, this key should be decrypted by the KMIP server.</td>      </tr>     </tbody>       </table>            </td>         </tr>         <tr>          <td>keyAltNames</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            An optional list of string alternate names used to reference a key.            If a key is created with alternate names, then encryption may refer            to the key by the unique alternate name instead of by            <span class="literal">_id</span>.           </span>          </td>         </tr>         <tr>          <td>keyMaterial</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span></td>          <td>           <span class="simpara">            An optional 96-byte value to use as custom key material for the data            key being created. If keyMaterial is given, the custom key material            is used for encrypting and decrypting data. Otherwise, the key            material for the new data key is generated from a cryptographically            secure random device.           </span>          </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.createdatakey-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the identifier of the new key as a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span> object with subtype 4 (UUID).  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.createdatakey-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> on other errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-clientencryption.createdatakey-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.20.0</td>      <td>       Added <span class="literal">"delegated"</span> to the KMIP provider masterKey options.      </td>     </tr>     <tr>      <td>PECL mongodb 1.15.0</td>      <td>       Added the <span class="literal">"keyMaterial"</span> option.      </td>     </tr>     <tr>      <td>PECL mongodb 1.10.0</td>      <td>       Azure and GCP are now supported as KMS providers for client-side       encryption.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
     * Creates a new key document and inserts into the key vault collection.
     * @link https://www.php.net/manual/en/mongodb-driver-clientencryption.createdatakey.php
     * @param string $kmsProvider The KMS provider ("local" or "aws") that will be used to encrypt the new encryption key.
     * @param array|null $options [optional]
     * @return Binary Returns the identifier of the new key as a MongoDB\BSON\Binary object with subtype 4 (UUID).
     * @throws InvalidArgumentException On argument parsing errors.
     * @throws EncryptionException If an error occurs while creating the data key.
     */
    final public function createDataKey(string $kmsProvider, ?array $options = null): Binary {}

    /**
 * <div id="mongodb-driver-clientencryption.decrypt" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::decrypt</h1>  <p class="verinfo">(mongodb &gt;=1.7.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::decrypt</span> — <span class="dc-title">Decrypt a value</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.decrypt-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::decrypt</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">   Decrypts the value.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.decrypt-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span></dt>    <dd>     <span class="simpara">      A <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span> instance with subtype 6      containing the encrypted value.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.decrypt-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the decrypted value as it was passed to   <span class="function">{@link MongoDB\Driver\ClientEncryption::encrypt()}</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.decrypt-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-encryptionexception.php" class="classname">MongoDB\Driver\Exception\EncryptionException</a></span> if an error occurs while decrypting the value</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-clientencryption.decrypt-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\ClientEncryption::encrypt()} - Encrypt a value</span></li>  </ul> </div></div>
 * 
     * Decrypts an encrypted value (BSON binary of subtype 6).
     * @link https://www.php.net/manual/en/mongodb-driver-clientencryption.decrypt.php
     * @param \MongoDB\BSON\BinaryInterface $keyVaultClient A MongoDB\BSON\Binary instance with subtype 6 containing the encrypted value.
     * @return mixed Returns the decrypted value
     * @throws InvalidArgumentException On argument parsing errors.
     * @throws EncryptionException If an error occurs while decrypting the value.
     */
    final public function decrypt(Binary $keyVaultClient) {}

    /**
 * <div id="mongodb-driver-clientencryption.deletekey" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::deleteKey</h1>  <p class="verinfo">(mongodb &gt;=1.15.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::deleteKey</span> — <span class="dc-title">Deletes a key document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.deletekey-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::deleteKey</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span> <span class="parameter" style="color:#3A95FF">\$keyId</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></div>  <p class="simpara">   Removes the key document with the given UUID <span class="parameter" style="color:#3A95FF">keyId</span>   from the key vault collection.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.deletekey-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">keyId</span></dt>    <dd>     <span class="simpara">      A <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span> instance with subtype 4      (UUID) identifying the key document.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.deletekey-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result of the internal <span class="literal">deleteOne</span> operation on   the key vault collection.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.deletekey-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> on other errors.</li>  </ul> </div></div>
 * 
     * Deletes a key document
     * @link https://www.php.net/manual/en/mongodb-driver-clientencryption.deletekey.php
     * @param Binary $keyId A MongoDB\BSON\Binary instance with subtype 4 (UUID) identifying the key document.
     * @return object Returns the result of the internal deleteOne operation on the key vault collection.
     * @throws InvalidArgumentException On argument parsing errors.
     * @since 1.15.0
     */
    final public function deleteKey(Binary $keyId): object {}

    /**
 * <div id="mongodb-driver-clientencryption.encrypt" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::encrypt</h1>  <p class="verinfo">(mongodb &gt;=1.7.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::encrypt</span> — <span class="dc-title">Encrypt a value</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.encrypt-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::encrypt</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span></div>  <p class="simpara">   Encrypts the value.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.encrypt-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span></dt>    <dd>     <span class="simpara">      The value to be encrypted. Any value that can be inserted into MongoDB can      be encrypted using this method.     </span>    </dd>             <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>Encryption options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>algorithm</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>           <span class="simpara">            The encryption algorithm to be used. This option is required.            Specify one of the following            <a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants" class="link">ClientEncryption constants</a>:           </span>           <ul class="simplelist">            <li><strong><span>MongoDB\Driver\ClientEncryption::AEAD_AES_256_CBC_HMAC_SHA_512_DETERMINISTIC</span></strong></li>            <li><strong><span>MongoDB\Driver\ClientEncryption::AEAD_AES_256_CBC_HMAC_SHA_512_RANDOM</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_UNINDEXED}</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong></li>           </ul>          </td>         </tr>         <tr>          <td>contentionFactor</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>          <td>           <span class="simpara">            The contention factor for evaluating queries with indexed, encrypted            payloads.           </span>           <span class="simpara">            This option only applies and may only be specified when            <span class="literal">algorithm</span> is            <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong>            or            <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong>.           </span>          </td>         </tr>         <tr>          <td>keyAltName</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>           <span class="simpara">            Identifies a key vault collection document by            <span class="literal">keyAltName</span>. This option is mutually exclusive            with <span class="literal">keyId</span> and exactly one is required.           </span>          </td>         </tr>         <tr>          <td>keyId</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span></td>          <td>           <span class="simpara">            Identifies a data key by <span class="literal">_id</span>. The value is a UUID            (binary subtype 4). This option is mutually exclusive with            <span class="literal">keyAltName</span> and exactly one is required.           </span>          </td>         </tr>         <tr>          <td>queryType</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>           <span class="simpara">            The query type for evaluating queries with indexed, encrypted            payloads. Specify one of the following            <a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants" class="link">ClientEncryption constants</a>:           </span>           <ul class="simplelist">            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_EQUALITY}</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_RANGE}</span></strong></li>           </ul>           <span class="simpara">            This option only applies and may only be specified when            <span class="literal">algorithm</span> is            <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong>            or <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong>.           </span>          </td>         </tr>         <tr>          <td>rangeOpts</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            Index options for a queryable encryption field supporting "range"            queries. The options below must match the values set in the            <span class="literal">encryptedFields</span> of the target collection. For            double and decimal128 BSON field types, <span class="literal">min</span>,            <span class="literal">max</span>, and <span class="literal">precision</span> must all be            set, or all be unset.           </span>           <p class="para">            </p><table class="doctable table">             <caption><strong>Range index options</strong></caption>                           <thead>               <tr>                <th>Option</th>                <th>Type</th>                <th>Description</th>               </tr>              </thead>              <tbody class="tbody">               <tr>                <td>min</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></td>                <td>                 Required if <span class="literal">precision</span> is set. The minimum                 BSON value of the range.                </td>               </tr>               <tr>                <td>max</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></td>                <td>                 Required if <span class="literal">precision</span> is set. The maximum                 BSON value of the range.                </td>               </tr>               <tr>                <td>sparsity</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>                <td>Optional. Positive 64-bit integer.</td>               </tr>               <tr>                <td>precision</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>                <td>                 Optional. Positive 32-bit integer specifying precision to use                 for explicit encryption. May only be set for double or                 decimal128 BSON field types.                </td>               </tr>               <tr>                <td>trimFactor</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>                <td>Optional. Positive 32-bit integer.</td>               </tr>              </tbody>                         </table>                     </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.encrypt-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the encrypted value as   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span> object with subtype 6.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.encrypt-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-encryptionexception.php" class="classname">MongoDB\Driver\Exception\EncryptionException</a></span> if an error occurs while encrypting the value</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-clientencryption.encrypt-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.20.0</td>      <td>       Added the <span class="literal">"trimFactor"</span> range option. The       <span class="literal">"sparsity"</span> range option is now optional.      </td>     </tr>     <tr>      <td>PECL mongodb 1.16.0</td>      <td>       Added the <span class="literal">"rangeOpts"</span> option.      </td>     </tr>     <tr>      <td>PECL mongodb 1.14.0</td>      <td>       Added the <span class="literal">"contentionFactor"</span> and       <span class="literal">"queryType"</span> options.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-clientencryption.encrypt-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\ClientEncryption::decrypt()} - Decrypt a value</span></li>   <li><span class="function">{@link MongoDB\Driver\ClientEncryption::encryptExpression()} - Encrypts a match or aggregate expression</span></li>  </ul> </div></div>
 * 
     * Encrypts a value with a given key and algorithm.
     * @link https://www.php.net/manual/en/mongodb-driver-clientencryption.encrypt.php
     * @param mixed $value The value to be encrypted. Any value that can be inserted into MongoDB can be encrypted using this method.
     * @param array|null $options [optional]
     * @return Binary Returns the encrypted value as MongoDB\BSON\Binary object with subtype 6.
     * @throws InvalidArgumentException On argument parsing errors.
     * @throws EncryptionException If an error occurs while encrypting the value.
     */
    final public function encrypt($value, ?array $options = null): Binary {}

    /**
 * <div id="mongodb-driver-clientencryption.encryptexpression" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::encryptExpression</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::encryptExpression</span> — <span class="dc-title">Encrypts a match or aggregate expression</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.encryptexpression-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::encryptExpression</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$expr</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></div>  <p class="simpara">   Encrypts a match or aggregate expression to query a range index.  </p>  <p class="simpara">To query with a range encrypted payload, the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span> must be configured with the <span class="literal">"autoEncryption"</span> driver option. The <span class="literal">"bypassQueryAnalysis"</span> auto encryption option may be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>. The <span class="literal">"bypassAutoEncryption"</span> auto encryption option must be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>.</p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">The extension does not yet support range queries for Decimal128 BSON field types.</span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.encryptexpression-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">expr</span></dt>    <dd>     <span class="simpara">      The match or aggregate expression to be encrypted. Expressions must use at      least one of the <span class="literal">\$gt</span>, <span class="literal">\$gte</span>,      <span class="literal">\$lt</span>, or <span class="literal">\$lte</span> operators. A top-level      <span class="literal">\$and</span> operator is required, even if only a single      comparison operator is used.     </span>     <span class="simpara">      An example of a supported match expression (applies to queries and the      <span class="literal">\$match</span> aggregation stage) is as follows:     </span>     <div class="example-contents"><div class="textcode"><blockquote style="border:1px gray solid;">[<br>&nbsp;&nbsp;&nbsp;&nbsp;'\$and'&nbsp;=&gt;&nbsp;[<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[&nbsp;'&lt;field&gt;'&nbsp;=&gt;&nbsp;[&nbsp;'\$gt'&nbsp;&nbsp;=&gt;&nbsp;'&lt;value1&gt;'&nbsp;]&nbsp;],<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[&nbsp;'&lt;field&gt;'&nbsp;=&gt;&nbsp;[&nbsp;'\$lte'&nbsp;=&gt;&nbsp;'&lt;value2&gt;'&nbsp;]&nbsp;],<br>&nbsp;&nbsp;&nbsp;&nbsp;],<br>]</blockquote></div>     </div>     <span class="simpara">      An example of a supported aggregate expression is as follows:     </span>     <div class="example-contents"><div class="textcode"><blockquote style="border:1px gray solid;">[<br>&nbsp;&nbsp;&nbsp;&nbsp;'\$and'&nbsp;=&gt;&nbsp;[<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[&nbsp;'\$gte'&nbsp;=&gt;&nbsp;[&nbsp;'&lt;fieldPath&gt;',&nbsp;'&lt;value1&gt;'&nbsp;]&nbsp;],<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[&nbsp;'\$lt'&nbsp;&nbsp;=&gt;&nbsp;[&nbsp;'&lt;fieldPath&gt;',&nbsp;'&lt;value2&gt;'&nbsp;]&nbsp;],<br>&nbsp;&nbsp;&nbsp;&nbsp;],<br>]</blockquote></div>     </div>    </dd>             <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>Encryption options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>algorithm</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>           <span class="simpara">            The encryption algorithm to be used. This option is required.            Specify one of the following            <a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants" class="link">ClientEncryption constants</a>:           </span>           <ul class="simplelist">            <li><strong><span>MongoDB\Driver\ClientEncryption::AEAD_AES_256_CBC_HMAC_SHA_512_DETERMINISTIC</span></strong></li>            <li><strong><span>MongoDB\Driver\ClientEncryption::AEAD_AES_256_CBC_HMAC_SHA_512_RANDOM</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_UNINDEXED}</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong></li>           </ul>          </td>         </tr>         <tr>          <td>contentionFactor</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>          <td>           <span class="simpara">            The contention factor for evaluating queries with indexed, encrypted            payloads.           </span>           <span class="simpara">            This option only applies and may only be specified when            <span class="literal">algorithm</span> is            <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong>            or            <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong>.           </span>          </td>         </tr>         <tr>          <td>keyAltName</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>           <span class="simpara">            Identifies a key vault collection document by            <span class="literal">keyAltName</span>. This option is mutually exclusive            with <span class="literal">keyId</span> and exactly one is required.           </span>          </td>         </tr>         <tr>          <td>keyId</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span></td>          <td>           <span class="simpara">            Identifies a data key by <span class="literal">_id</span>. The value is a UUID            (binary subtype 4). This option is mutually exclusive with            <span class="literal">keyAltName</span> and exactly one is required.           </span>          </td>         </tr>         <tr>          <td>queryType</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>           <span class="simpara">            The query type for evaluating queries with indexed, encrypted            payloads. Specify one of the following            <a href="https://php.net/manual/zh/class.mongodb-driver-clientencryption.php#mongodb-driver-clientencryption.constants" class="link">ClientEncryption constants</a>:           </span>           <ul class="simplelist">            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_EQUALITY}</span></strong></li>            <li><strong><span>{@link MongoDB\Driver\ClientEncryption::QUERY_TYPE_RANGE}</span></strong></li>           </ul>           <span class="simpara">            This option only applies and may only be specified when            <span class="literal">algorithm</span> is            <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_INDEXED}</span></strong>            or <strong><span>{@link MongoDB\Driver\ClientEncryption::ALGORITHM_RANGE}</span></strong>.           </span>          </td>         </tr>         <tr>          <td>rangeOpts</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            Index options for a queryable encryption field supporting "range"            queries. The options below must match the values set in the            <span class="literal">encryptedFields</span> of the target collection. For            double and decimal128 BSON field types, <span class="literal">min</span>,            <span class="literal">max</span>, and <span class="literal">precision</span> must all be            set, or all be unset.           </span>           <p class="para">            </p><table class="doctable table">             <caption><strong>Range index options</strong></caption>                           <thead>               <tr>                <th>Option</th>                <th>Type</th>                <th>Description</th>               </tr>              </thead>              <tbody class="tbody">               <tr>                <td>min</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></td>                <td>                 Required if <span class="literal">precision</span> is set. The minimum                 BSON value of the range.                </td>               </tr>               <tr>                <td>max</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></td>                <td>                 Required if <span class="literal">precision</span> is set. The maximum                 BSON value of the range.                </td>               </tr>               <tr>                <td>sparsity</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>                <td>Optional. Positive 64-bit integer.</td>               </tr>               <tr>                <td>precision</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>                <td>                 Optional. Positive 32-bit integer specifying precision to use                 for explicit encryption. May only be set for double or                 decimal128 BSON field types.                </td>               </tr>               <tr>                <td>trimFactor</td>                <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>                <td>Optional. Positive 32-bit integer.</td>               </tr>              </tbody>                         </table>                     </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.encryptexpression-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the encrypted expression as an object.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.encryptexpression-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-encryptionexception.php" class="classname">MongoDB\Driver\Exception\EncryptionException</a></span> if an error occurs while encrypting the expression</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-clientencryption.encryptexpression-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.20.0</td>      <td>       Added the <span class="literal">"trimFactor"</span> range option. The       <span class="literal">"sparsity"</span> range option is now optional.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-clientencryption.encryptexpression-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Manager::__construct()} - Create new MongoDB Manager</span></li>   <li><span class="function">{@link MongoDB\Driver\ClientEncryption::encrypt()} - Encrypt a value</span></li>  </ul> </div></div>
 * 
     * Encrypts a Match Expression or Aggregate Expression to query a range index
     * @param array|object $expr A BSON document containing the expression
     * @param array|null $options
     * @return object Returns the encrypted expression as a BSON document
     * @throws InvalidArgumentException On argument parsing errors.
     * @since 1.16.0
     */
    final public function encryptExpression(array|object $expr, ?array $options = null): object {}

    /**
 * <div id="mongodb-driver-clientencryption.getkey" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::getKey</h1>  <p class="verinfo">(mongodb &gt;=1.15.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::getKey</span> — <span class="dc-title">Gets a key document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.getkey-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::getKey</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span> <span class="parameter" style="color:#3A95FF">\$keyId</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></div>  <p class="simpara">   Finds a single key document in the key vault collection with the given UUID   <span class="parameter" style="color:#3A95FF">keyId</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.getkey-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">keyId</span></dt>    <dd>     <span class="simpara">      A <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="classname">MongoDB\BSON\Binary</a></span> instance with subtype 4      (UUID) identifying the key document.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.getkey-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the key document, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no document matched.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.getkey-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> on other errors.</li>  </ul> </div></div>
