    /**
 * <div id="mongodb-driver-clientencryption.rewrapmanydatakey" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ClientEncryption::rewrapManyDataKey</h1>  <p class="verinfo">(mongodb &gt;=1.15.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ClientEncryption::rewrapManyDataKey</span> — <span class="dc-title">Rewraps data keys</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-clientencryption.rewrapmanydatakey-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ClientEncryption::rewrapManyDataKey</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$filter</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></div>  <p class="simpara">   Rewraps (i.e. decrypts and re-encrypts) zero or more data keys in the key   vault collection that match the given <span class="parameter" style="color:#3A95FF">filter</span>.  </p>  <p class="simpara">   If the <span class="literal">"provider"</span> option is not specified, matching data   keys will be rewrapped with their current KMS provider. Otherwise, matching   data keys will be re-encrypted according to the specified   <span class="literal">"provider"</span> and <span class="literal">"masterKey"</span> options.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-clientencryption.rewrapmanydatakey-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">filter</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>)</dt>    <dd>     <span class="simpara">      The <a href="https://www.mongodb.com/docs/manual/tutorial/query-documents/" class="link external">»&nbsp;query predicate</a>.      An empty predicate will match all documents in the collection.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       When evaluating query criteria, MongoDB compares types and values according to its own <a href="https://www.mongodb.com/docs/manual/reference/bson-type-comparison-order/" class="link external">»&nbsp;comparison rules for BSON types</a>, which differs from PHP's <a href="https://php.net/manual/zh/types.comparisons.php" class="link">comparison</a> and <a href="https://php.net/manual/zh/language.types.type-juggling.php" class="link">type juggling</a> rules. When matching a special BSON type the query criteria should use the respective <a href="https://php.net/manual/zh/mongodb.bson.php" class="link">BSON class</a> (e.g. use <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> to match an <a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId</a>).      </span>     </p></blockquote>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>RewrapManyDataKey options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>provider</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></td>          <td>           <span class="simpara">            The KMS provider (e.g. <span class="literal">"local"</span>,            <span class="literal">"aws"</span>) that will be used to re-encrypt the            matched data keys.           </span>           <span class="simpara">            If a KMS provider is not specified, matched data keys will be            re-encrypted with their current KMS provider.           </span>          </td>         </tr>         <tr>          <td>masterKey</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            The masterKey identifies a KMS-specific key used to encrypt the new            data key. This option should not be specified without the            <span class="literal">"provider"</span> option. This option is required if            <span class="literal">"provider"</span> is specified and not            <span class="literal">"local"</span>.           </span>             <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"aws"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>region</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>key</td>       <td>string</td>       <td>Required. The Amazon Resource Name (ARN) to the AWS customer master key (CMK).</td>      </tr>      <tr>       <td>endpoint</td>       <td>string</td>       <td>Optional. An alternate host identifier to send KMS requests to. May include port number.</td>      </tr>     </tbody>       </table>    <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"azure"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>keyVaultEndpoint</td>       <td>string</td>       <td>Required. Host with optional port (e.g. "example.vault.azure.net").</td>      </tr>      <tr>       <td>keyName</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyVersion</td>       <td>string</td>       <td>Optional. A specific version of the named key. Defaults to using the key's primary version.</td>      </tr>     </tbody>       </table>    <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"gcp"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>projectId</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>location</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyRing</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyName</td>       <td>string</td>       <td>Required.</td>      </tr>      <tr>       <td>keyVersion</td>       <td>string</td>       <td>Optional. A specific version of the named key. Defaults to using the key's primary version.</td>      </tr>      <tr>       <td>endpoint</td>       <td>string</td>       <td>Optional. Host with optional port. Defaults to "cloudkms.googleapis.com".</td>      </tr>     </tbody>       </table>    <p class="para">   </p><table class="doctable table">    <caption><strong><span class="literal">"kmip"</span> provider options</strong></caption>         <thead>      <tr>       <th>Option</th>       <th>Type</th>       <th>Description</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>keyId</td>       <td>string</td>       <td>Optional. Unique identifier to a 96-byte KMIP secret data managed object. If unspecified, the driver creates a random 96-byte KMIP secret data managed object.</td>      </tr>      <tr>       <td>endpoint</td>       <td>string</td>       <td>Optional. Host with optional port.</td>      </tr>      <tr>       <td>delegated</td>       <td>bool</td>       <td>Optional. If true, this key should be decrypted by the KMIP server.</td>      </tr>     </tbody>       </table>            </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-clientencryption.rewrapmanydatakey-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an object, which will have an optional   <span class="literal">bulkWriteResult</span> property containing the result of the   internal <span class="literal">bulkWrite</span> operation as an object. If no data keys   matched the filter or the write was unacknowledged, the   <span class="literal">bulkWriteResult</span> property will be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-clientencryption.rewrapmanydatakey-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-encryptionexception.php" class="classname">MongoDB\Driver\Exception\EncryptionException</a></span> if an error occurs while decrypting or re-encrypting a data key.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> on other errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-clientencryption.rewrapmanydatakey-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.20.0</td>      <td>       Added <span class="literal">"delegated"</span> to the KMIP provider masterKey options.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
     * Rewraps data keys
     * @link https://www.php.net/manual/en/mongodb-driver-clientencryption.rewrapmanydatakey.php
     * @param array|object $filter
     * @param array|null $options
     * @return object Returns an object, which will have an optional bulkWriteResult property containing the result of the internal bulkWrite operation as an object. If no data keys matched the filter or the write was unacknowledged, the bulkWriteResult property will be null.
     * @since 1.16.0
     */
    final public function rewrapManyDataKey(array|object $filter, ?array $options = null): object {}
}
